bun run - <<'EOF'
import { readFileSync } from 'fs'
const lines = readFileSync('.werk/log.jsonl','utf8').trim().split('\n').map(l=>JSON.parse(l))
const refines = [] // {from,to}
const nodes = new Map() // id -> {title,status}
const reopened = new Map() // id -> {reason,seq}
for (const e of lines) {
  if (e.type === 'node.added') nodes.set(e.payload.id, {title: e.payload.title, status: e.payload.status, kind: e.payload.kind})
  if (e.type === 'edge.added' && e.payload.type === 'refines') refines.push({from: e.payload.from, to: e.payload.to})
  if (e.type === 'status.set') { const n = nodes.get(e.payload.id); if(n) n.status = e.payload.status }
  if (e.type === 'reopened') reopened.set(e.payload.id, {reason: e.payload.reason ?? 'invalidated', seq: e.seq})
}
// children map: parent -> [child]
const children = new Map()
for (const {from,to} of refines) {
  const l = children.get(to) ?? []
  l.push(from)
  children.set(to, l)
}
const seen = new Set()
const queue = ['product']
const result = []
while(queue.length) {
  const cur = queue.shift()
  for (const c of children.get(cur) ?? []) {
    if (seen.has(c)) continue
    seen.add(c)
    queue.push(c)
    const n = nodes.get(c)
    result.push({id: c, title: n?.title, status: n?.status, kind: n?.kind, reopened: reopened.get(c)})
  }
}
for (const r of result) console.log(JSON.stringify(r))
EOF

