const d=JSON.parse(require("fs").readFileSync("/tmp/g.json","utf8"));
const byId=new Map(d.nodes.map(n=>[n.id,n]));const isC=id=>byId.get(id)?.kind==="card";
const kids=new Map();for(const e of d.edges)if(e.type==="refines"){(kids.get(e.to)??kids.set(e.to,[]).get(e.to)).push(e.from)}
const sub=id=>{const s=new Set([id]),q=[id];while(q.length)for(const k of kids.get(q.shift())??[])if(!s.has(k)){s.add(k);q.push(k)}return new Set([...s].filter(isC))};
const deps=d.edges.filter(e=>e.type==="depends_on"&&isC(e.from)&&isC(e.to));
const part=new Map([["root","root"]]);for(const k of kids.get("root")??[])for(const id of sub(k))part.set(id,k);
console.log("deps",deps.length,"cross",deps.filter(e=>part.has(e.from)&&part.has(e.to)&&part.get(e.from)!==part.get(e.to)).length);
for(const k of (kids.get("root")??[]).filter(isC)){const s=sub(k);let i=0,o=0;for(const e of deps){const f=s.has(e.from),t=s.has(e.to);if(f&&!t)o++;else if(t&&!f)i++}console.log(k,s.size,i+"/"+o)}'

