ops=$(curl -s localhost:4000/api/graph | bun -e '
const g = JSON.parse(await Bun.stdin.text());
const n = g.nodes.find(n => n.id === "st-build-howto-titles");
const OLD = "A card has one parent, so each card sits on one side. A card is a build rule when a user of the product would not notice a change to it. A card that a user would notice is a requirement, even when it names a technology.";
const NEW = "A card has one parent, so each card sits on one side. A card is a build rule when it holds only for this project’s own repository: its stack, its tooling, its conventions. A card is a requirement when it states what the product does for the people who use it, even when it names a technology. When the product itself builds software, a rule it applies to every project it builds is a requirement. The way its own repository follows that rule is a build rule, and it depends on the requirement.";
const blocks = n.body.split(/\n\n+/);
if (!blocks.includes(OLD)) throw new Error("block not found");
console.log(JSON.stringify(blocks.map(b => ({ tag: "elaborated", old: b, new: b === OLD ? NEW : b }))));
')
werk propose st-build-howto-titles --ops "$ops" 2>&1 | grep -v "^$" | head -8

